import{_ as a,o as t,c as i,a2 as d}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"开发前端","description":"了解 Ershu 前端的边界、目录、请求方式和新增页面的完整验证流程。","frontmatter":{"page_id":"development-frontend","description":"了解 Ershu 前端的边界、目录、请求方式和新增页面的完整验证流程。"},"headers":[],"relativePath":"development/frontend.md","filePath":"development/frontend.md","lastUpdated":1786290726000}'),s={name:"development/frontend.md"};function l(o,e,n,r,p,c){return t(),i("div",null,[...e[0]||(e[0]=[d(`<h1 id="开发前端" tabindex="-1">开发前端 <a class="header-anchor" href="#开发前端" aria-label="Permalink to &quot;开发前端&quot;">​</a></h1><p>Ershu 前端是独立仓库。它负责浏览器界面、浏览器状态和 HTTP 请求，不导入 Core、API、Worker 或 MCP 的源码。修改页面前，应先通过正在运行的 Ershu 和已发布接口确认约定，不能用本机恰好存在的后端目录补出隐含依赖。</p><h2 id="技术与运行边界" tabindex="-1">技术与运行边界 <a class="header-anchor" href="#技术与运行边界" aria-label="Permalink to &quot;技术与运行边界&quot;">​</a></h2><p>当前前端使用：</p><ul><li>Node.js 24；</li><li>Vite 7；</li><li>React 19；</li><li>React Router 的 Hash 路由；</li><li>TypeScript；</li><li>Tailwind CSS 和 Radix 组件；</li><li><code>markdown-it</code>、Mermaid 和知识图谱组件。</li></ul><p>Hash 路由让静态文件可以承载运行时页面。中文页面地址形如 <code>#/zh/projects</code>，英文页面形如 <code>#/en/projects</code>。</p><p>前端只知道公开 HTTP 约定。后台队列、权限判断、文档生成和搜索实现仍由后端负责；界面不能把本地推测当成服务端事实。</p><h2 id="目录职责" tabindex="-1">目录职责 <a class="header-anchor" href="#目录职责" aria-label="Permalink to &quot;目录职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>作用</th></tr></thead><tbody><tr><td><code>src/app.tsx</code></td><td>路由、登录保护、项目布局和全局提供器</td></tr><tr><td><code>src/pages/</code></td><td>与路由对应的轻量页面入口</td></tr><tr><td><code>src/features/</code></td><td>页面控制器、视图和可单独测试的状态逻辑</td></tr><tr><td><code>lib/api/</code></td><td>请求方法、请求和响应类型、Cookie 与 CSRF 处理</td></tr><tr><td><code>lib/api-client.ts</code></td><td>汇总各组 API 客户端</td></tr><tr><td><code>lib/auth-context.tsx</code></td><td>登录状态、会话恢复、刷新和退出</td></tr><tr><td><code>lib/i18n.ts</code></td><td>中文和英文消息读取与路径语言解析</td></tr><tr><td><code>messages/zh.json</code>、<code>messages/en.json</code></td><td>两种语言的界面文字</td></tr><tr><td><code>lib/theme-provider.tsx</code></td><td>亮色、暗色和跟随系统主题</td></tr><tr><td><code>components/</code></td><td>通用布局和界面组件</td></tr><tr><td><code>hooks/</code></td><td>事件流和通用交互钩子</td></tr></tbody></table><p>新增功能时，优先把请求放在 <code>lib/api/</code>，把可复用状态放在 <code>src/features/</code>，让 <code>src/pages/</code> 只负责组合。这样页面入口不会同时承担请求、状态、渲染和文案。</p><h2 id="启动本地前端" tabindex="-1">启动本地前端 <a class="header-anchor" href="#启动本地前端" aria-label="Permalink to &quot;启动本地前端&quot;">​</a></h2><p>在独立的 frontend 仓库中执行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>开发服务器默认监听 <code>http://localhost:3000</code>。成功后，终端中的开发进程应保持运行，浏览器访问该地址会进入首次管理员设置、登录或项目列表中的一个，而不是显示静态空白页。</p><p>本地构建变量只有四项：</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>作用</th></tr></thead><tbody><tr><td><code>VITE_API_BASE_URL</code></td><td><code>/api/v1</code></td><td>浏览器请求的 API 基础路径</td></tr><tr><td><code>VITE_CSRF_COOKIE_NAME</code></td><td><code>ershu_csrf</code></td><td>CSRF Cookie 名称</td></tr><tr><td><code>VITE_DEV_API_PROXY</code></td><td><code>http://localhost:8000</code></td><td>开发环境的 API 代理目标</td></tr><tr><td><code>VITE_DEV_MCP_PROXY</code></td><td><code>http://127.0.0.1:8001</code></td><td>开发环境的 MCP 代理目标</td></tr></tbody></table><p>修改代理目标后要重启开发服务器。模型名称、模型 API Key 和模型通道地址不属于这些构建变量，它们由管理员在网页后台配置。</p><h2 id="新增或修改一个页面" tabindex="-1">新增或修改一个页面 <a class="header-anchor" href="#新增或修改一个页面" aria-label="Permalink to &quot;新增或修改一个页面&quot;">​</a></h2><h3 id="_1-先确认接口约定" tabindex="-1">1. 先确认接口约定 <a class="header-anchor" href="#_1-先确认接口约定" aria-label="Permalink to &quot;1. 先确认接口约定&quot;">​</a></h3><p>通过运行中的 Ershu MCP、接口文档和实际响应确认：</p><ul><li>路径和请求方法；</li><li>请求和响应字段；</li><li>权限要求；</li><li>失败状态；</li><li>长任务是否使用快照、事件流或最终结果。</li></ul><p>确认完成后，你应能指出界面每个字段来自哪个公开响应，而不是引用后端内部对象。</p><h3 id="_2-扩展-api-客户端" tabindex="-1">2. 扩展 API 客户端 <a class="header-anchor" href="#_2-扩展-api-客户端" aria-label="Permalink to &quot;2. 扩展 API 客户端&quot;">​</a></h3><p>在 <code>lib/api/</code> 对应模块中增加请求和类型，并从客户端入口导出。请求应继续使用已有的公共请求层，以保持 Cookie、CSRF、错误解析和刷新行为一致。</p><p>如果请求提交密码、Token、SSH 密钥或模型 API Key，还要沿用安全传输检查。本机地址可以用于开发，其他主机名必须使用 HTTPS。</p><p>完成后，请求方法应能由功能代码导入，且没有页面直接拼接另一个 API 基础地址。</p><h3 id="_3-把状态和视图放进功能目录" tabindex="-1">3. 把状态和视图放进功能目录 <a class="header-anchor" href="#_3-把状态和视图放进功能目录" aria-label="Permalink to &quot;3. 把状态和视图放进功能目录&quot;">​</a></h3><p>在 <code>src/features/&lt;feature&gt;/</code> 中拆分：</p><ul><li>负责加载和提交的控制器；</li><li>负责展示的视图；</li><li>不依赖浏览器的状态转换和辅助函数；</li><li>对这些纯逻辑的测试。</li></ul><p>完成后，状态切换、权限显示和失败处理应能在不复制页面组件的情况下被检查。</p><h3 id="_4-接入页面和路由" tabindex="-1">4. 接入页面和路由 <a class="header-anchor" href="#_4-接入页面和路由" aria-label="Permalink to &quot;4. 接入页面和路由&quot;">​</a></h3><p>在 <code>src/pages/</code> 添加轻量入口，再在 <code>src/app.tsx</code> 中使用延迟加载接入路由。项目内页面放在 <code>/:locale/projects/:projectId</code> 下；全局管理页面放在现有工作区结构下。</p><p>成功后，中英文地址都能进入同一页面，并且未登录用户仍会回到对应语言的登录页。</p><h3 id="_5-同步中英文文字" tabindex="-1">5. 同步中英文文字 <a class="header-anchor" href="#_5-同步中英文文字" aria-label="Permalink to &quot;5. 同步中英文文字&quot;">​</a></h3><p>在 <code>messages/zh.json</code> 和 <code>messages/en.json</code> 添加相同结构的消息键。不要在组件中写只属于一种语言的提示，也不要让错误回退提示只显示英文。</p><p>切换语言后，当前页面路径和对象编号应保持不变，只替换语言段和界面文字。</p><h3 id="_6-保持现有长任务语义" tabindex="-1">6. 保持现有长任务语义 <a class="header-anchor" href="#_6-保持现有长任务语义" aria-label="Permalink to &quot;6. 保持现有长任务语义&quot;">​</a></h3><p>运行详情必须区分活动状态和终止状态：</p><ul><li>活动运行先读取快照，再从游标之后连接事件流；</li><li><code>completed</code> 和 <code>completed_with_warnings</code> 直接读取最终结果；</li><li><code>failed</code> 和 <code>cancelled</code> 不应继续连接事件流；</li><li>刷新页面不能创建新的运行。</li></ul><p>Docs 中的聊天当前是项目范围。不要因为用户正在阅读某篇文档，就在请求中声称聊天已经变成文档或章节范围。</p><h2 id="验证改动" tabindex="-1">验证改动 <a class="header-anchor" href="#验证改动" aria-label="Permalink to &quot;验证改动&quot;">​</a></h2><p>提交前按顺序运行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>判定标准：</p><ul><li><code>npm test</code> 以退出码 <code>0</code> 结束；</li><li><code>npm run lint</code> 同时通过代码检查和 TypeScript 检查；</li><li><code>npm run format:check</code> 没有列出需要重新排版的文件；</li><li><code>npm run build</code> 以退出码 <code>0</code> 结束，并生成 <code>dist/</code>。</li></ul><p>当前自动测试主要覆盖状态逻辑、请求约定和事件处理，不是完整的浏览器端到端测试。还需要手工检查：</p><ul><li>中文和英文路由；</li><li>亮色、暗色和跟随系统主题；</li><li>375 像素左右的窄屏和常见桌面宽度；</li><li>键盘操作和焦点；</li><li>登录失效、请求失败和空数据；</li><li>活动运行刷新与完成态加载。</li></ul><p>如果某项检查失败，请按<a href="./troubleshooting">开发故障排查</a>定位原因，不要通过删除测试或放宽接口类型来掩盖问题。</p>`,48)])])}const u=a(s,[["render",l]]);export{k as __pageData,u as default};
